    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    diagonals = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                r, c = r1, c1
                while True:
                    out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc
                diagonals.append((r1, c1, r2, c2))

    for r, c in sixes:
        for r1, c1, r2, c2 in diagonals:
            # The 6 must lie on a diagonal connecting two 1s.
            if abs(r-r1) == abs(c-c1) and (r-r1)*(c2-c1) == (c-c1)*(r2-r1):
                # Extend the 6 in the perpendicular diagonal direction.
                dr = 1 if (r2-r1) == (c2-c1) else 1
                dc = -1 if (r2-r1) == (c2-c1) else 1
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != 1:
                        out[rr][cc] = 6
                    rr -= dr
                    cc -= dc
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != 1:
                        out[rr][cc] = 6
                    rr += dr
                    cc += dc
                break
    return out
